using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Interop;

namespace QiDesk {
public static class ShellFeatureTests {
    public static void MakePicture(string path,bool reverse){
        byte[] pixels=new byte[160*80*4];for(int y=0;y<80;y++)for(int x=0;x<160;x++){int n=(y*160+x)*4;bool red=(x<80)!=reverse;pixels[n]=20;pixels[n+1]=(byte)(red?25:220);pixels[n+2]=(byte)(red?230:20);pixels[n+3]=255;}
        var source=BitmapSource.Create(160,80,96,96,PixelFormats.Bgra32,null,pixels,640);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(source));using(var file=File.Create(path))png.Save(file);
    }
    static bool Picture(BitmapSource source,bool reverse){if(source==null||source.PixelWidth<20||source.PixelHeight<10)return false;var bitmap=new FormatConvertedBitmap(source,PixelFormats.Bgra32,null,0);byte[] pixels=new byte[bitmap.PixelWidth*bitmap.PixelHeight*4];bitmap.CopyPixels(pixels,bitmap.PixelWidth*4,0);int left=((bitmap.PixelHeight/2)*bitmap.PixelWidth+bitmap.PixelWidth/4)*4,right=((bitmap.PixelHeight/2)*bitmap.PixelWidth+3*bitmap.PixelWidth/4)*4;return reverse?pixels[left+1]>150&&pixels[left+2]<100&&pixels[right+2]>150:pixels[left+2]>150&&pixels[left+1]<100&&pixels[right+1]>150;}
    public static void Run(string root,Controller controller,Window owner,Action<bool,string> check){
        string folder=Path.Combine(root,"shell-preview");Directory.CreateDirectory(folder);string image=Path.Combine(folder,"picture.png"),text=Path.Combine(folder,"test.txt");MakePicture(image,false);File.WriteAllText(text,"Native menu fixture");
        var thumbnail=Thumbnails.Extract(image,96);check(Picture(thumbnail,false),"Windows thumbnail contains actual picture pixels rather than file-type icon");check(Math.Abs((double)thumbnail.PixelWidth/thumbnail.PixelHeight-2)<.1,"picture thumbnail preserves source aspect ratio");string firstKey=Thumbnails.Key(image,96);MakePicture(image,true);File.SetLastWriteTimeUtc(image,DateTime.UtcNow.AddSeconds(2));check(firstKey!=Thumbnails.Key(image,96),"thumbnail cache key changes when picture contents are updated");
        using(var exclusive=File.Open(image,FileMode.Open,FileAccess.ReadWrite,FileShare.None))check(exclusive.Length>0,"thumbnail extraction releases the image file for rename and editing");
        byte[] alphaPixels=new byte[80*40*4];for(int y=10;y<30;y++)for(int x=10;x<30;x++)alphaPixels[(y*80+x)*4+3]=255;string transparent=Path.Combine(folder,"alpha.png");var alphaPng=new PngBitmapEncoder();alphaPng.Frames.Add(BitmapFrame.Create(BitmapSource.Create(80,40,96,96,PixelFormats.Bgra32,null,alphaPixels,320)));using(var output=File.Create(transparent))alphaPng.Save(output);var alphaImage=new FormatConvertedBitmap(Thumbnails.Extract(transparent,320),PixelFormats.Bgra32,null,0);byte[] decoded=new byte[alphaImage.PixelWidth*alphaImage.PixelHeight*4];alphaImage.CopyPixels(decoded,alphaImage.PixelWidth*4,0);int center=((alphaImage.PixelHeight/2)*alphaImage.PixelWidth+alphaImage.PixelWidth/4)*4;check(decoded[3]==0&&decoded[center+3]>200&&decoded[center+2]<10,"large PNG preview preserves transparent background and opaque black artwork");
        string broken=Path.Combine(folder,"broken.png");File.WriteAllText(broken,"not a picture");check(Thumbnails.Extract(broken,96)==null,"corrupt picture falls back without crashing thumbnail extraction");
        IntPtr hwnd=new WindowInteropHelper(owner).Handle;string[] itemLabels,backgroundLabels;
        using(var menu=new NativeMenus(hwnd,text,false)){menu.AddGroupCommands(new[]{new NativeMenuCommand("仅在此分区忽略",delegate{})});itemLabels=menu.Inspect();check(itemLabels.Any(x=>x.EndsWith("|copy"))&&itemLabels.Any(x=>x.EndsWith("|delete"))&&itemLabels.Any(x=>x.EndsWith("|properties")),"file context menu is built by Windows Shell with copy delete and properties verbs");check(itemLabels.Any(x=>x.EndsWith("|rename"))&&itemLabels.Any(x=>x.StartsWith("栖桌|")),"native rename and separate organizer submenu coexist");}
        using(var menu=new NativeMenus(hwnd,folder,true)){menu.AddBackgroundCommands(new NativeMenuCommand("配置桌面分区",delegate{}),new[]{new NativeMenuCommand("大图标",delegate{})},new[]{new NativeMenuCommand("名称",delegate{})},delegate{});menu.AddPasteCommands(folder,delegate{});backgroundLabels=menu.Inspect();check(backgroundLabels.Any(x=>x.Contains("查看"))&&backgroundLabels.Any(x=>x.Contains("排序方式"))&&backgroundLabels.Any(x=>x.Contains("刷新")),"folder background native menu integrates view sort and refresh for the custom view");check(backgroundLabels.Any(x=>x.Contains("新建"))&&backgroundLabels.Any(x=>x.Contains("粘贴")),"folder background combines native new commands with clipboard-aware paste");}
        File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"shell-menu-results.txt"),new[]{"FILE MENU"}.Concat(itemLabels).Concat(new[]{"BACKGROUND MENU"}).Concat(backgroundLabels));
        string copyTarget=Path.Combine(folder,"copied");Directory.CreateDirectory(copyTarget);var copyData=(System.Runtime.InteropServices.ComTypes.IDataObject)(object)new DataObject(DataFormats.FileDrop,new[]{text});NativeMenus.PasteData(hwnd,copyTarget,copyData,1,false);WaitFor(Path.Combine(copyTarget,"test.txt"));check(File.Exists(text)&&File.ReadAllText(Path.Combine(copyTarget,"test.txt"))=="Native menu fixture","Windows file operation copies fixture files without touching user clipboard");
        string moveTarget=Path.Combine(folder,"moved");Directory.CreateDirectory(moveTarget);string movedSource=Path.Combine(copyTarget,"test.txt");var moveData=(System.Runtime.InteropServices.ComTypes.IDataObject)(object)new DataObject(DataFormats.FileDrop,new[]{movedSource});NativeMenus.PasteData(hwnd,moveTarget,moveData,2,false);WaitFor(Path.Combine(moveTarget,"test.txt"));check(!File.Exists(movedSource)&&File.Exists(Path.Combine(moveTarget,"test.txt")),"Windows file operation preserves cut versus copy semantics on fixtures");
        string renamePath=Path.Combine(moveTarget,"renamed.txt");check(ShellActions.Rename(owner,Path.Combine(moveTarget,"test.txt"),"renamed.txt")&&File.ReadAllText(renamePath)=="Native menu fixture","Windows native rename preserves fixture file contents");
        string link=NativeFileOperations.Shortcut(copyTarget,text),secondLink=NativeFileOperations.Shortcut(copyTarget,text);check(File.Exists(link)&&File.Exists(secondLink)&&link!=secondLink&&File.Exists(text),"paste shortcut creates native links without replacing existing shortcuts or source files");
        var store=controller.Store;var group=new Group(){Name="Thumbnail fixture",Width=380,Height=260,IconSize=96};group.Items.Add(image);store.Data.Groups.Add(group);var window=new FenceWindow(controller,group);try{window.Show();window.UpdateLayout();Thumbnails.Drain(4000);var pictures=Images(window).Where(i=>i.Source is BitmapSource).ToArray();check(pictures.Any(i=>Picture(i.Source as BitmapSource,true)),"visible large desktop tile asynchronously displays actual updated thumbnail");}finally{window.Close();store.Data.Groups.Remove(group);}
        string before=Path.Combine(folder,"old"),after=Path.Combine(folder,"new");var state=new State();var g=new Group(){Folder=before};g.Items.Add(Path.Combine(before,"child.txt"));g.IgnoreRules.Add(new IgnoreRule(){Kind="路径",Pattern=g.Items[0]});state.Groups.Add(g);state.WorkFolders.Add(before);ShellActions.UpdateReferences(state,before,after,true);check(g.Folder==after&&g.Items[0]==Path.Combine(after,"child.txt")&&g.IgnoreRules[0].Pattern==g.Items[0]&&state.WorkFolders[0]==after,"native rename reference updates retain groups ignore rules and workspace identity");
    }
    static void WaitFor(string path){var watch=System.Diagnostics.Stopwatch.StartNew();while(!File.Exists(path)&&watch.ElapsedMilliseconds<3000){Thumbnails.Drain(20);System.Threading.Thread.Sleep(10);}}
    static IEnumerable<Image> Images(DependencyObject root){var image=root as Image;if(image!=null)yield return image;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Images(VisualTreeHelper.GetChild(root,i)))yield return child;}
}
}
